<?php
declare(strict_types=1); namespace Vendor\ContaoIssueServiceBundle\Tests\Unit\Application; use PHPUnit\Framework\Attributes\DataProvider; use PHPUnit\Framework\TestCase; use Vendor\ContaoIssueServiceBundle\Application\WorkflowPolicy; use Vendor\ContaoIssueServiceBundle\Domain\Enum\IssueStatus;
final class WorkflowPolicyTest extends TestCase { #[DataProvider('allowed')] public function testAllows(IssueStatus $a,IssueStatus $b):void{self::assertTrue((new WorkflowPolicy())->allows($a,$b));} public static function allowed():iterable{yield[IssueStatus::New,IssueStatus::Triage];yield[IssueStatus::InProgress,IssueStatus::Resolved];yield[IssueStatus::Closed,IssueStatus::InProgress];} public function testRejectsIllegalTransition():void{$this->expectException(\DomainException::class);(new WorkflowPolicy())->assertAllowed(IssueStatus::New,IssueStatus::Closed);} }
